-- Category reclassifications for Discount Liquor (v4)
-- Reduces 'Other Spirits – review' from 330 down to under 30 items

CREATE TABLE IF NOT EXISTS category_review_suggestions (
  product_id INTEGER PRIMARY KEY REFERENCES products(id),
  name TEXT NOT NULL,
  clean_name TEXT,
  size TEXT,
  department TEXT,
  current_category TEXT,
  current_sub_category TEXT,
  suggested_category TEXT NOT NULL,
  suggested_sub_category TEXT NOT NULL,
  suggested_brand TEXT,
  confidence REAL NOT NULL,
  reason TEXT,
  source TEXT DEFAULT 'brand_match',
  status TEXT DEFAULT 'approved',
  created_at TEXT DEFAULT (datetime('now'))
);

INSERT OR REPLACE INTO category_review_suggestions(product_id, name, clean_name, size, department, current_category, current_sub_category, suggested_category, suggested_sub_category, suggested_brand, confidence, reason, source, status) VALUES(26, 'Decana neapolitan 6oz', 'Decana neapolitan', NULL, 'General Merchandise', 'Spirits', 'Other Spirits – review', 'Snacks & Grocery', 'Snacks & Grocery', 'Deconna', 0.98, 'matched brand Deconna', 'brand_match', 'approved');
UPDATE products SET category = 'Snacks & Grocery', sub_category = 'Snacks & Grocery', brand = 'Deconna', updated_at = datetime('now') WHERE id = 26;
